def compute(vars):
    interest_payments = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    ratio = interest_payments / total_contractual_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "interest_payments": interest_payments,
            "total_contractual_obligations": total_contractual_obligations,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
